static void read_line(char *buffer, size_t size)
{
    if (fgets(buffer, (int)size, stdin) == NULL) {
        buffer[0] = '\0';
        return;
    }
    buffer[strcspn(buffer, "\r\n")] = '\0';
}

int main(void)
{
    char buffer[1024];
    read_line(buffer, sizeof buffer);

    int value = 0;
    if (parse_int(buffer, &value)) {
        printf("ok %d\n", value);
    } else {
        printf("bad\n");
    }
    return 0;
}

