"""Random numerals for the parser.

The invalid cases are made by taking a valid numeral and dropping one
character into it that cannot appear in a number. That is a property of the
edit, not something anyone here had to go and check.
"""

JUNK = "abcxyzQZ_%*/. ,"


def generate(rng, count):
    builders = (_positive, _negative, _leading_zeros, _spoilt)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _numeral(rng):
    return str(rng.randint(1, 2000000000))


def _positive(rng, index):
    return _case("a positive number #%d" % index, _numeral(rng))


def _negative(rng, index):
    return _case("a negative number #%d" % index, "-" + _numeral(rng))


def _leading_zeros(rng, index):
    text = "0" * rng.randint(1, 4) + str(rng.randint(0, 9999))
    if rng.random() < 0.3:
        text = "-" + text
    return _case("padded with zeros #%d" % index, text,
                 "Leading zeros do not change the value and do not make the "
                 "string invalid.")


def _spoilt(rng, index):
    text = _numeral(rng)
    if rng.random() < 0.4:
        text = rng.choice("+-") + text
    where = rng.randint(1, len(text))
    spoilt = text[:where] + rng.choice(JUNK) + text[where:]
    return _case("not a number #%d" % index, spoilt,
                 "A valid numeral with one character in it that cannot be part "
                 "of a number.")
